 * Deterministic topological ordering of a dependency graph.
 *
 * A graph is a plain object whose own enumerable keys are node ids and whose
 * values are arrays of successor ids; an edge `a -> b` means `a` must come
 * before `b`.
 */

/**
 * Compares two node ids as UTF-16 code unit sequences (never localeCompare).
 * @param {string} a First id.
 * @param {string} b Second id.
 * @returns {number} Negative, zero, or positive per `<`/`>` on strings.
 */
function compareIds(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

/**
 * Validates the graph shape and returns its node ids.
 * @param {unknown} graph Candidate dependency graph.
 * @returns {string[]} Own enumerable node ids, in insertion order.
 */
function validateGraph(graph) {
  if (typeof graph !== 'object' || graph === null || Array.isArray(graph)) {
    throw new TypeError('graph must be an object');
  }
  const nodes = Object.keys(graph);
  for (const node of nodes) {
    const value = graph[node];
    if (!Array.isArray(value) || !value.every((item) => typeof item === 'string')) {
      throw new TypeError(`edge list for node "${node}" must be an array`);
    }
  }
  const known = new Set(nodes);
  for (const node of nodes) {
    for (const target of graph[node]) {
      if (!known.has(target)) {
        throw new ReferenceError(`unknown node: "${target}"`);
      }
    }
  }
  return nodes;
}

/**
 * Builds deduplicated, ascending-sorted adjacency lists.
 * @param {Record<string, string[]>} graph Validated dependency graph.
 * @param {string[]} nodes Node ids.
 * @returns {Map<string, string[]>} Node id to sorted, deduplicated successors.
 */
function buildAdjacency(graph, nodes) {
  const adj = new Map();
  for (const node of nodes) {
    adj.set(node, [...new Set(graph[node])].sort(compareIds));
  }
  return adj;
}

/**
 * Rotates a cycle so it starts at its smallest id, preserving order.
 * @param {string[]} cycle Cycle in discovery order.
 * @returns {string[]} Rotated cycle.
 */
function rotateToSmallest(cycle) {
  let minIndex = 0;
  for (let i = 1; i < cycle.length; i += 1) {
    if (compareIds(cycle[i], cycle[minIndex]) < 0) minIndex = i;
  }
  return cycle.slice(minIndex).concat(cycle.slice(0, minIndex));
}

/**
 * Finds one cycle in the graph, searching nodes and successors in ascending
 * id order and reporting the first back edge to a node on the current path.
 * @param {string[]} nodes Node ids.
 * @param {Map<string, string[]>} adj Sorted adjacency lists.
 * @returns {string[] | null} Cycle rotated to its smallest id, or null.
 */
function findCycleNodes(nodes, adj) {
  const WHITE = 0;
  const GRAY = 1;
  const BLACK = 2;
  const state = new Map(nodes.map((node) => [node, WHITE]));
  const path = [];

  function visit(node) {
    state.set(node, GRAY);
    path.push(node);
    for (const next of adj.get(node)) {
      const nextState = state.get(next);
      if (nextState === GRAY) {
        const index = path.indexOf(next);
        return rotateToSmallest(path.slice(index));
      }
      if (nextState === WHITE) {
        const found = visit(next);
        if (found) return found;
      }
    }
    state.set(node, BLACK);
    path.pop();
    return null;
  }

  const sortedNodes = [...nodes].sort(compareIds);
  for (const node of sortedNodes) {
    if (state.get(node) === WHITE) {
      const found = visit(node);
      if (found) return found;
    }
  }
  return null;
}

/**
 * Finds one cycle, exploring nodes and successors in ascending id order.
 * @param {unknown} graph Dependency graph.
 * @returns {string[] | null} Cycle in edge order starting at its smallest id, or null.
 */
export function findCycle(graph) {
  const nodes = validateGraph(graph);
  const adj = buildAdjacency(graph, nodes);
  return findCycleNodes(nodes, adj);
}

/**
 * Orders the graph with Kahn's algorithm, always taking the smallest ready id.
 * @param {unknown} graph Dependency graph.
 * @returns {{ok: true, order: string[]} | {ok: false, cycle: string[]}} Order or cycle.
 */
export function kahnOrder(graph) {
  const nodes = validateGraph(graph);
  const adj = buildAdjacency(graph, nodes);

  const indegree = new Map(nodes.map((node) => [node, 0]));
  for (const node of nodes) {
    for (const succ of adj.get(node)) {
      indegree.set(succ, indegree.get(succ) + 1);
    }
  }

  const ready = nodes.filter((node) => indegree.get(node) === 0).sort(compareIds);
  const order = [];
  while (ready.length > 0) {
    const node = ready.shift();
    order.push(node);
    for (const succ of adj.get(node)) {
      const remaining = indegree.get(succ) - 1;
      indegree.set(succ, remaining);
      if (remaining === 0) {
        const index = ready.findIndex((candidate) => compareIds(candidate, succ) > 0);
        if (index === -1) ready.push(succ);
        else ready.splice(index, 0, succ);
      }
    }
  }

  if (order.length !== nodes.length) {
    return { ok: false, cycle: findCycleNodes(nodes, adj) };
  }
  return { ok: true, order };
}

/**
 * Orders the graph by reversed depth-first finishing times.
 * @param {unknown} graph Dependency graph.
 * @returns {{ok: true, order: string[]} | {ok: false, cycle: string[]}} Order or cycle.
 */
export function dfsOrder(graph) {
  const nodes = validateGraph(graph);
  const adj = buildAdjacency(graph, nodes);

  const cycle = findCycleNodes(nodes, adj);
  if (cycle) return { ok: false, cycle };

  const visited = new Set();
  const finished = [];

  function visit(node) {
    visited.add(node);
    for (const succ of adj.get(node)) {
      if (!visited.has(succ)) visit(succ);
    }
    finished.push(node);
  }

  const sortedNodes = [...nodes].sort(compareIds);
  for (const node of sortedNodes) {
    if (!visited.has(node)) visit(node);
  }

  return { ok: true, order: finished.reverse() };
}

/**
 * Groups nodes into dependency levels: a node sits one level below its deepest
 * predecessor, and each level is listed in ascending id order.
 * @param {unknown} graph Dependency graph.
 * @returns {{ok: true, layers: string[][]} | {ok: false, cycle: string[]}} Levels or cycle.
 */
export function layers(graph) {
  const nodes = validateGraph(graph);
  const adj = buildAdjacency(graph, nodes);

  const cycle = findCycleNodes(nodes, adj);
  if (cycle) return { ok: false, cycle };

  const predecessors = new Map(nodes.map((node) => [node, []]));
  for (const node of nodes) {
    for (const succ of adj.get(node)) {
      predecessors.get(succ).push(node);
    }
  }

  const depth = new Map();
  function levelOf(node) {
    if (depth.has(node)) return depth.get(node);
    let best = 0;
    for (const pred of predecessors.get(node)) {
      best = Math.max(best, levelOf(pred) + 1);
    }
    depth.set(node, best);
    return best;
  }

  let maxLevel = -1;
  for (const node of nodes) {
    maxLevel = Math.max(maxLevel, levelOf(node));
  }

  const result = [];
  for (let i = 0; i <= maxLevel; i += 1) result.push([]);
  for (const node of nodes) result[depth.get(node)].push(node);
  for (const group of result) group.sort(compareIds);

  return { ok: true, layers: result };
}
